using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using Newtonsoft.Json.Linq;
public static class InstallSurfaceClothing {
 public static object Run(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");const string path="Assets/_Sandbox/Characters/Ethan_V2/Ethan_V2.prefab";var root=PrefabUtility.LoadPrefabContents(path);try{
 var all=root.GetComponentsInChildren<SkinnedMeshRenderer>(true);var body=all.Single(r=>r.name=="BAKED_body_lod0_mesh");var cloth=all.Single(r=>r.name=="BAKED_Outfits_LOD0");cloth.sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/_Sandbox/Characters/Ethan_V2/Meshes/EthanV2_Outfit_BodyBound.asset");cloth.enabled=true;
 var json=JObject.Parse(File.ReadAllText("Data/EthanV2/ClothingRepair/surface_bindings.json"));var positions=JObject.Parse(File.ReadAllText("Data/EthanV2/ClothingRepair/binding_input.json"))["clothVertices"];var data=new CharacterGarmentSurfaceBinding.Binding[cloth.sharedMesh.vertexCount];
 for(int i=0;i<data.Length;i++){var t=json["triangles"][i];var b=json["bary"][i];var o=json["offsets"][i];var v=positions[i];float x=Mathf.Abs((float)v[0]),y=(float)v[1];float blend=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.06f,.11f,x))*Mathf.SmoothStep(0,1,Mathf.InverseLerp(1.18f,1.28f,y));if(json["influences"]!=null)blend=(float)json["influences"][i];data[i]=new CharacterGarmentSurfaceBinding.Binding{a=(int)t[0],b=(int)t[1],c=(int)t[2],barycentric=new Vector3((float)b[0],(float)b[1],(float)b[2]),offset=new Vector3((float)o[0],(float)o[1],(float)o[2]),influence=blend};}
 var component=root.GetComponent<CharacterGarmentSurfaceBinding>();if(!component)component=root.AddComponent<CharacterGarmentSurfaceBinding>();component.Configure(root.transform,body,cloth,data);PrefabUtility.SaveAsPrefabAsset(root,path);AssetDatabase.SaveAssets();return new{bindings=data.Length,fullBodyTriangles=body.sharedMesh.triangles.Length/3,runtimeOnly=true};
 }finally{PrefabUtility.UnloadPrefabContents(root);}}
}
